={{ (() => {
  const j = $json;
  const escapeHtml = (value) => String(value === undefined || value === null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
  const text = (value) => String(value === undefined || value === null ? '' : value).trim();

  const eventLabel = text(j.event_type) === 'scheduler_heartbeat_missing'
    ? 'Scheduled job did not run / heartbeat missing'
    : 'Download job failed';

  const stage = text(j.safe_failure_stage) || 'unknown';
  const message = text(j.safe_error_message) || 'Unknown workflow error';
  const supportRef = text(j.safe_support_ref);
  const runId = text(j.safe_run_id);
  const exitCode = text(j.safe_exit_code);
  const workflowName = text(j.safe_error_workflow_name);
  const executionId = text(j.safe_execution_id);
  const stamp = (escapeHtml(text(j.logged_date)) + ' ' + escapeHtml(text(j.logged_time))).trim();

  const lines = ['<b>\ud83d\udea8 EnergyGrid Download Error</b>', ''];
  lines.push('Event: ' + eventLabel);
  lines.push('Stage: <code>' + stage + '</code>');
  lines.push('Error: ' + message);
  if (supportRef) lines.push('Reference: <code>' + supportRef + '</code>');
  if (runId) lines.push('Run: <code>' + runId + '</code>');
  if (exitCode) lines.push('Exit code: <code>' + exitCode + '</code>');
  if (stamp) lines.push('Time: ' + stamp + ' SGT');
  if (workflowName && workflowName !== 'Unknown workflow') lines.push('n8n workflow: ' + workflowName);
  if (executionId) lines.push('n8n execution: <code>' + executionId + '</code>');

  return lines.join('\n');
})() }}
